  7 |     int n, i, best, cur;
  8 |     scanf("%d", &n);
  9 |     for (i = 0; i < n; i++) scanf("%d", &a[i]);
 10 |     best = a[0]; cur = a[0];
 11 |     for (i = 1; i < n; i++) {
 12 |         cur = cur + a[i] > a[i] ? cur + a[i] : a[i];   /* bug: int overflows past 2^31 */
 13 |         if (cur > best) best = cur;
 14 |     }
